1	import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
2	import { useTriggerStore } from '../../store/useTriggerStore';
3	import { ConditionEntry } from '../../types/schema';
4	import { ConditionManager } from '../../utils/conditionManager';
5	import { generateHexId } from '../../utils/hexId';
6	import { NotionCategorySelect } from './NotionCategorySelect';
7	import {
8	  ShieldAlert,
9	  Plus,
10	  Search,
11	  Layers,
12	  Sparkles,
13	  Trash2,
14	  Copy,
15	  Save,
16	  RotateCcw,
17	  Check,
18	  X,
19	  AlertTriangle,
20	  Folder,
21	  ChevronLeft,
22	  ChevronRight,
23	  MoveHorizontal,
24	  Flame,
25	  CheckSquare,
26	} from 'lucide-react';
27	
28	const PRESET_CATEGORIES = [
29	  'All',
30	  'Subject',
31	  'Pose',
32	  'Apparel',
33	  'Environment',
34	  'Camera',
35	  'Expression',
36	  'Lighting',
37	  'Art Style',
38	  'General',
39	];
40	
41	export const ConditionsManagerView: React.FC = () => {
42	  const { app, reload } = useTriggerStore();
43	
44	  const [conditions, setConditions] = useState<Record<string, ConditionEntry>>({});
45	  const [workingConditions, setWorkingConditions] = useState<Record<string, ConditionEntry>>({});
46	  const [isLoading, setIsLoading] = useState(true);
47	  const [isDirty, setIsDirty] = useState(false);
48	  const [dirtyCount, setDirtyCount] = useState(0);
49	  const [isSaving, setIsSaving] = useState(false);
50	  const [saveSuccessNotice, setSaveSuccessNotice] = useState(false);
51	
52	  // Selected Category filter tab
53	  const [selectedCategory, setSelectedCategory] = useState<string>('All');
54	  const [searchQuery, setSearchQuery] = useState('');
55	  const [filterMode, setFilterMode] = useState<'all' | 'completed' | 'draft' | 'conflicts'>('all');
56	
57	  // Load conditions from disk
58	  const loadData = useCallback(async () => {
59	    if (!app) return;
60	    setIsLoading(true);
61	    const data = await ConditionManager.loadAllConditions(app);
62	    setConditions(data);
63	    setWorkingConditions(JSON.parse(JSON.stringify(data)));
64	    setIsDirty(false);
65	    setDirtyCount(0);
66	    setIsLoading(false);
67	  }, [app]);
68	
69	  useEffect(() => {
70	    loadData();
71	  }, [loadData]);
72	
73	  // --- HORIZONTAL NOTION-STYLE DRAG & WALL EDGE NAVIGATION ---
74	  const tableContainerRef = useRef<HTMLDivElement>(null);
75	  const isDraggingRef = useRef(false);
76	  const startXRef = useRef(0);
77	  const startScrollLeftRef = useRef(0);
78	  const edgeScrollAnimRef = useRef<number | null>(null);
79	
80	  const [canScrollLeft, setCanScrollLeft] = useState(false);
81	  const [canScrollRight, setCanScrollRight] = useState(false);
82	  const [scrollProgress, setScrollProgress] = useState(0);
83	
84	  const checkScrollBoundaries = useCallback(() => {
85	    const el = tableContainerRef.current;
86	    if (!el) return;
87	    const maxScroll = el.scrollWidth - el.clientWidth;
88	    setCanScrollLeft(el.scrollLeft > 4);
89	    setCanScrollRight(el.scrollLeft < maxScroll - 4);
90	    setScrollProgress(maxScroll > 0 ? (el.scrollLeft / maxScroll) * 100 : 0);
91	  }, []);
92	
93	  useEffect(() => {
94	    checkScrollBoundaries();
95	    window.addEventListener('resize', checkScrollBoundaries);
96	    return () => window.removeEventListener('resize', checkScrollBoundaries);
97	  }, [checkScrollBoundaries, workingConditions]);
98	
99	  const scrollHorizontally = useCallback((delta: number) => {
100	    if (!tableContainerRef.current) return;
101	    tableContainerRef.current.scrollBy({ left: delta, behavior: 'smooth' });
102	    setTimeout(checkScrollBoundaries, 200);
103	  }, [checkScrollBoundaries]);
104	
105	  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
106	    const target = e.target as HTMLElement;
107	    if (
108	      target.tagName === 'INPUT' ||
109	      target.tagName === 'TEXTAREA' ||
110	      target.tagName === 'SELECT' ||
111	      target.tagName === 'BUTTON' ||
112	      target.closest('button') ||
113	      target.closest('select') ||
114	      target.closest('input') ||
115	      target.closest('textarea')
116	    ) {
117	      return;
118	    }
119	
120	    if (!tableContainerRef.current) return;
121	    isDraggingRef.current = true;
122	    startXRef.current = e.clientX;
123	    startScrollLeftRef.current = tableContainerRef.current.scrollLeft;
124	  };
125	
126	  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
127	    if (!tableContainerRef.current) return;
128	    const el = tableContainerRef.current;
129	    const rect = el.getBoundingClientRect();
130	
131	    if (isDraggingRef.current) {
132	      const dx = e.clientX - startXRef.current;
133	      el.scrollLeft = startScrollLeftRef.current - dx;
134	      checkScrollBoundaries();
135	    }
136	
137	    const distToRight = rect.right - e.clientX;
138	    const distToLeft = e.clientX - rect.left;
139	
140	    if (edgeScrollAnimRef.current) {
141	      cancelAnimationFrame(edgeScrollAnimRef.current);
142	      edgeScrollAnimRef.current = null;
143	    }
144	
145	    if (distToRight >= 0 && distToRight < 60) {
146	      const speed = Math.max(2, Math.round((60 - distToRight) * 0.4));
147	      const step = () => {
148	        if (tableContainerRef.current) {
149	          tableContainerRef.current.scrollLeft += speed;
150	          checkScrollBoundaries();
151	        }
152	      };
153	      edgeScrollAnimRef.current = requestAnimationFrame(step);
154	    } else if (distToLeft >= 0 && distToLeft < 60) {
155	      const speed = Math.max(2, Math.round((60 - distToLeft) * 0.4));
156	      const step = () => {
157	        if (tableContainerRef.current) {
158	          tableContainerRef.current.scrollLeft -= speed;
159	          checkScrollBoundaries();
160	        }
161	      };
162	      edgeScrollAnimRef.current = requestAnimationFrame(step);
163	    }
164	  };
165	
166	  const handleMouseUpOrLeave = () => {
167	    isDraggingRef.current = false;
168	    if (edgeScrollAnimRef.current) {
169	      cancelAnimationFrame(edgeScrollAnimRef.current);
170	      edgeScrollAnimRef.current = null;
171	    }
172	    checkScrollBoundaries();
173	  };
174	
175	  const handleWheel = (e: React.WheelEvent<HTMLDivElement>) => {
176	    if (!tableContainerRef.current) return;
177	    if (e.shiftKey || Math.abs(e.deltaX) > 0) {
178	      tableContainerRef.current.scrollLeft += e.deltaX || e.deltaY;
179	      checkScrollBoundaries();
180	    }
181	  };
182	
183	  // Convert working conditions dictionary to array
184	  const entriesList = useMemo(() => {
185	    return Object.entries(workingConditions).map(([key, entry]) => ({
186	      key,
187	      entry,
188	    }));
189	  }, [workingConditions]);
190	
191	  // Available categories with counts
192	  const categoryCounts = useMemo(() => {
193	    const counts: Record<string, number> = { All: entriesList.length };
194	    entriesList.forEach(({ entry }) => {
195	      const cat = entry.category || 'General';
196	      counts[cat] = (counts[cat] || 0) + 1;
197	    });
198	    return counts;
199	  }, [entriesList]);
200	
201	  const categoriesList = useMemo(() => {
202	    const set = new Set([...PRESET_CATEGORIES, ...Object.keys(categoryCounts)]);
203	    return Array.from(set);
204	  }, [categoryCounts]);
205	
206	  // Counts for status
207	  const completedCount = useMemo(() => entriesList.filter((e) => Boolean(e.entry.completed)).length, [entriesList]);
208	  const draftCount = useMemo(() => entriesList.filter((e) => !e.entry.completed).length, [entriesList]);
209	  const conflictCount = useMemo(() => entriesList.filter((e) => e.entry.conflicts_with && e.entry.conflicts_with.length > 0).length, [entriesList]);
210	
211	  // Filtered rows
212	  const filteredEntries = useMemo(() => {
213	    return entriesList.filter(({ key, entry }) => {
214	      // Category filter
215	      if (selectedCategory !== 'All' && (entry.category || 'General').toLowerCase() !== selectedCategory.toLowerCase()) {
216	        return false;
217	      }
218	
219	      // Status filters
220	      if (filterMode === 'completed' && !entry.completed) return false;
221	      if (filterMode === 'draft' && Boolean(entry.completed)) return false;
222	      if (filterMode === 'conflicts' && (!entry.conflicts_with || entry.conflicts_with.length === 0)) return false;
223	
224	      // Search query
225	      if (!searchQuery.trim()) return true;
226	      const q = searchQuery.toLowerCase();
227	      return (
228	        key.toLowerCase().includes(q) ||
229	        (entry.display_name && entry.display_name.toLowerCase().includes(q)) ||
230	        (entry.description && entry.description.toLowerCase().includes(q)) ||
231	        (entry.category && entry.category.toLowerCase().includes(q))
232	      );
233	    });
234	  }, [entriesList, selectedCategory, searchQuery, filterMode]);
235	
236	  // Helper to update working copy
237	  const updateField = useCallback((key: string, field: keyof ConditionEntry, value: any) => {
238	    setWorkingConditions((prev) => ({
239	      ...prev,
240	      [key]: {
241	        ...prev[key],
242	        [field]: value,
243	      },
244	    }));
245	    setIsDirty(true);
246	    setDirtyCount((prev) => prev + 1);
247	  }, []);
248	
249	  // Save changes to disk
250	  const handleSaveToDisk = useCallback(async () => {
251	    if (!app || isSaving) return;
252	    setIsSaving(true);
253	
254	    const success = await ConditionManager.saveAllConditions(app, workingConditions);
255	    if (success) {
256	      setConditions(JSON.parse(JSON.stringify(workingConditions)));
257	      setIsDirty(false);
258	      setDirtyCount(0);
259	      setSaveSuccessNotice(true);
260	      setTimeout(() => setSaveSuccessNotice(false), 2000);
261	      await reload();
262	    } else {
263	      window.alert('Failed to save conditions to conditions.json.');
264	    }
265	    setIsSaving(false);
266	  }, [app, workingConditions, isSaving, reload]);
267	
268	  // Discard changes
269	  const handleDiscardChanges = () => {
270	    if (window.confirm('Discard all unsaved edits in Conditions?')) {
271	      setWorkingConditions(JSON.parse(JSON.stringify(conditions)));
272	      setIsDirty(false);
273	      setDirtyCount(0);
274	    }
275	  };
276	
277	  // Keyboard shortcut: Ctrl+S / Cmd+S to save
278	  useEffect(() => {
279	    const handleKeyDown = (e: KeyboardEvent) => {
280	      if ((e.ctrlKey || e.metaKey) && e.key === 's') {
281	        e.preventDefault();
282	        if (isDirty) {
283	          handleSaveToDisk();
284	        }
285	      }
286	    };
287	    window.addEventListener('keydown', handleKeyDown);
288	    return () => window.removeEventListener('keydown', handleKeyDown);
289	  }, [isDirty, handleSaveToDisk]);
290	
291	  // Add new Condition row
292	  const handleAddNewCondition = () => {
293	    const newHex = generateHexId();
294	    const newEntry: ConditionEntry = {
295	      display_name: 'New Condition',
296	      category: selectedCategory !== 'All' ? selectedCategory : 'General',
297	      description: '',
298	      completed: false,
299	      tag_team: [],
300	      conflicts_with: [],
301	    };
302	
303	    setWorkingConditions((prev) => ({
304	      ...prev,
305	      [newHex]: newEntry,
306	    }));
307	    setIsDirty(true);
308	    setDirtyCount((prev) => prev + 1);
309	  };
310	
311	  // Duplicate Condition row
312	  const handleDuplicateCondition = (key: string, entry: ConditionEntry) => {
313	    const newHex = generateHexId();
314	    const duplicated: ConditionEntry = {
315	      ...JSON.parse(JSON.stringify(entry)),
316	      display_name: `${entry.display_name || key} (Copy)`,
317	      completed: false,
318	    };
319	
320	    setWorkingConditions((prev) => ({
321	      ...prev,
322	      [newHex]: duplicated,
323	    }));
324	    setIsDirty(true);
325	    setDirtyCount((prev) => prev + 1);
326	  };
327	
328	  // Delete Condition row
329	  const handleDeleteCondition = (key: string) => {
330	    setWorkingConditions((prev) => {
331	      const updated = { ...prev };
332	      delete updated[key];
333	      return updated;
334	    });
335	    setIsDirty(true);
336	    setDirtyCount((prev) => prev + 1);
337	  };
338	
339	  // Toggle Tag-Team implied condition
340	  const handleToggleTagTeam = (key: string, currentTagTeam: string[] | undefined, targetKey: string) => {
341	    const list = Array.isArray(currentTagTeam) ? [...currentTagTeam] : [];
342	    const exists = list.includes(targetKey);
343	    const updated = exists ? list.filter((k) => k !== targetKey) : [...list, targetKey];
344	    updateField(key, 'tag_team', updated);
345	  };
346	
347	  // Toggle Conflicts-With condition
348	  const handleToggleConflict = (key: string, currentConflicts: string[] | undefined, targetKey: string) => {
349	    const list = Array.isArray(currentConflicts) ? [...currentConflicts] : [];
350	    const exists = list.includes(targetKey);
351	    const updated = exists ? list.filter((k) => k !== targetKey) : [...list, targetKey];
352	    updateField(key, 'conflicts_with', updated);
353	  };
354	
355	  return (
356	    <div className="flex flex-col gap-6 w-full animate-fadeIn select-none">
357	      {/* TOP HEADER */}
358	      <div className="p-6 rounded-3xl bg-hazard-card/90 border border-hazard-border shadow-lg flex flex-wrap items-center justify-between gap-4">
359	        <div className="flex items-center gap-4">
360	          <div className="flex items-center justify-center w-12 h-12 rounded-2xl bg-hazard-cyan/10 border border-hazard-cyan/30 text-hazard-cyan shadow-sm">
361	            <ShieldAlert className="w-6 h-6" />
362	          </div>
363	          <div>
364	            <div className="flex items-center gap-2">
365	              <h2 className="text-lg font-bold uppercase tracking-wider text-hazard-textBright">
366	                Conditions & Collision Physics Registry
367	              </h2>
368	              <span className="px-2 py-0.5 rounded-md bg-hazard-cyan/15 border border-hazard-cyan/40 text-hazard-cyan text-[10px] font-mono font-bold">
369	                Condition Engine
370	              </span>
371	            </div>
372	            <p className="text-xs text-hazard-textMuted font-mono mt-0.5">
373	              Defines semantic scene states, prerequisite condition nodes, tag-team bundling, and mutual exclusion collision rules.
374	            </p>
375	          </div>
376	        </div>
377	
378	        {/* Action: Create Condition */}
379	        <button
380	          type="button"
381	          onClick={handleAddNewCondition}
382	          className="flex items-center gap-2 px-5 py-2.5 rounded-xl font-bold text-xs uppercase tracking-wider bg-gradient-to-r from-hazard-cyan to-hazard-cyan hover:brightness-110 text-black shadow-sm hover:scale-[1.02] active:scale-95 transition"
383	        >
384	          <Plus className="w-4 h-4" />
385	          <span>New Condition</span>
386	        </button>
387	      </div>
388	
389	      {/* TOP HORIZONTAL CATEGORY SELECTOR */}
390	      <div className="flex flex-col gap-3 p-4 rounded-3xl bg-hazard-card/90 border border-hazard-border shadow-md">
391	        <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-none">
392	          <span className="text-xs font-bold uppercase tracking-wider text-hazard-textMuted font-mono mr-2 shrink-0 flex items-center gap-1.5">
393	            <Folder className="w-3.5 h-3.5 text-hazard-cyan" />
394	            <span>Categories:</span>
395	          </span>
396	          {categoriesList.map((cat) => {
397	            const count = categoryCounts[cat] || 0;
398	            const isSelected = selectedCategory.toLowerCase() === cat.toLowerCase();
399	
400	            return (
401	              <button
402	                key={cat}
403	                type="button"
404	                onClick={() => setSelectedCategory(cat)}
405	                className={`flex items-center gap-2 px-3.5 py-2 rounded-xl text-xs font-bold transition select-none whitespace-nowrap shrink-0 ${
406	                  isSelected
407	                    ? 'bg-hazard-cyan text-black font-extrabold shadow-sm scale-[1.02]'
408	                    : 'bg-hazard-void text-hazard-textMuted hover:text-white hover:bg-hazard-cardHover border border-hazard-border'
409	                }`}
410	              >
411	                <span>{cat}</span>
412	                <span
413	                  className={`text-[10px] px-1.5 py-0.2 rounded-md ${
414	                    isSelected ? 'bg-black/25 text-black' : 'bg-hazard-card text-hazard-textMuted/70'
415	                  }`}
416	                >
417	                  {count}
418	                </span>
419	              </button>
420	            );
421	          })}
422	        </div>
423	      </div>
424	
425	      {/* NOTION DATABASE TABLE FOR CONDITIONS */}
426	      <div className="flex flex-col gap-3 p-5 rounded-3xl bg-hazard-card border border-hazard-border shadow-lg w-full relative">
427	        {/* Toolbar: Category Title, Search, Filters & Save */}
428	        <div className="flex flex-wrap items-center justify-between gap-4 pb-3 border-b border-hazard-border">
429	          {/* Left: Category Title */}
430	          <div className="flex items-center gap-3">
431	            <div className="flex items-center justify-center w-10 h-10 rounded-xl bg-hazard-cyan/10 border border-hazard-cyan/30 text-hazard-cyan">
432	              <Layers className="w-5 h-5" />
433	            </div>
434	            <div>
435	              <div className="flex items-center gap-2">
436	                <h3 className="text-base font-bold text-hazard-textBright uppercase tracking-wide">
437	                  {selectedCategory} Conditions
438	                </h3>
439	                <span className="px-2 py-0.5 rounded bg-hazard-void border border-hazard-border text-hazard-cyan text-[10px] font-mono">
440	                  {filteredEntries.length} rows
441	                </span>
442	                <span className="hidden sm:inline-flex items-center gap-1 text-[10px] font-mono text-hazard-textMuted/70 bg-hazard-void px-2 py-0.5 rounded border border-hazard-border">
443	                  <MoveHorizontal className="w-3 h-3 text-hazard-cyan" />
444	                  <span>Left-click & Drag or move to wall to pan horizontally</span>
445	                </span>
446	              </div>
447	              <p className="text-[11px] text-hazard-textMuted font-mono">
448	                Storage: <code className="text-hazard-cyan">Hazard_Trigger_Data/Conditions/conditions.json</code>
449	              </p>
450	            </div>
451	          </div>
452	
453	          {/* Right: Search, Status Filters & Save */}
454	          <div className="flex flex-wrap items-center gap-3">
455	            {/* Filter Pills */}
456	            <div className="flex items-center gap-1 bg-hazard-void p-1 rounded-xl border border-hazard-border text-[10px] font-mono">
457	              <button
458	                type="button"
459	                onClick={() => setFilterMode('all')}
460	                className={`px-2.5 py-1 rounded-lg transition ${
461	                  filterMode === 'all'
462	                    ? 'bg-hazard-card text-hazard-cyan font-bold shadow-sm'
463	                    : 'text-hazard-textMuted hover:text-white'
464	                }`}
465	              >
466	                All ({entriesList.length})
467	              </button>
468	              <button
469	                type="button"
470	                onClick={() => setFilterMode('completed')}
471	                className={`px-2.5 py-1 rounded-lg transition ${
472	                  filterMode === 'completed'
473	                    ? 'bg-emerald-500/20 text-emerald-300 font-bold border border-emerald-400/40 shadow-sm'
474	                    : 'text-hazard-textMuted hover:text-white'
475	                }`}
476	              >
477	                Done ({completedCount})
478	              </button>
479	              <button
480	                type="button"
481	                onClick={() => setFilterMode('draft')}
482	                className={`px-2.5 py-1 rounded-lg transition ${
483	                  filterMode === 'draft'
484	                    ? 'bg-sky-500/20 text-sky-300 font-bold border border-sky-400/40 shadow-sm'
485	                    : 'text-hazard-textMuted hover:text-white'
486	                }`}
487	              >
488	                Draft ({draftCount})
489	              </button>
490	              <button
491	                type="button"
492	                onClick={() => setFilterMode('conflicts')}
493	                className={`px-2.5 py-1 rounded-lg transition ${
494	                  filterMode === 'conflicts'
495	                    ? 'bg-rose-500/20 text-rose-300 font-bold border border-rose-400/40 shadow-sm'
496	                    : 'text-hazard-textMuted hover:text-white'
497	                }`}
498	              >
499	                Collisions ({conflictCount})
500	              </button>
501	            </div>
502	
503	            {/* Search Input */}
504	            <div className="flex items-center gap-1.5 bg-hazard-void border border-hazard-border rounded-xl px-3 py-1.5 min-w-[180px]">
505	              <Search className="w-3.5 h-3.5 text-hazard-textMuted" />
506	              <input
507	                type="text"
508	                placeholder="Filter conditions..."
509	                value={searchQuery}
510	                onChange={(e) => setSearchQuery(e.target.value)}
511	                className="w-full bg-transparent text-xs text-hazard-textBright placeholder:text-hazard-textMuted/40 outline-none font-mono"
512	              />
513	            </div>
514	
515	            {/* Add Row Button */}
516	            <button
517	              type="button"
518	              onClick={handleAddNewCondition}
519	              className="flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs font-bold font-mono bg-hazard-card border border-hazard-cyan/40 text-hazard-cyan hover:bg-hazard-cyan hover:text-black transition active:scale-95"
520	            >
521	              <Plus className="w-3.5 h-3.5" />
522	              <span>+ Condition</span>
523	            </button>
524	
525	            {/* Save Status & Button */}
526	            {isDirty ? (
527	              <div className="flex items-center gap-2 animate-pulse">
528	                <button
529	                  type="button"
530	                  onClick={handleDiscardChanges}
531	                  title="Discard all unsaved edits in Conditions"
532	                  className="p-2 text-hazard-crimson hover:bg-hazard-crimson/20 border border-hazard-crimson/40 rounded-xl transition text-xs font-mono"
533	                >
534	                  <RotateCcw className="w-4 h-4" />
535	                </button>
536	
537	                <button
538	                  type="button"
539	                  onClick={handleSaveToDisk}
540	                  disabled={isSaving}
541	                  title="Save conditions to conditions.json (Ctrl+S)"
542	                  className="flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold font-mono bg-gradient-to-r from-hazard-cyan to-hazard-cyan hover:brightness-110 text-black shadow-sm hover:scale-105 active:scale-95 transition"
543	                >
544	                  <Save className="w-4 h-4" />
545	                  <span>Save ({dirtyCount} edits)</span>
546	                </button>
547	              </div>
548	            ) : saveSuccessNotice ? (
549	              <span className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-emerald-950/80 border border-emerald-500/50 text-emerald-400 text-xs font-mono font-bold">
550	                <Check className="w-4 h-4" />
551	                <span>Saved to JSON!</span>
552	              </span>
553	            ) : null}
554	          </div>
555	        </div>
556	
557	        {/* Scroll Progress Bar */}
558	        <div className="w-full h-1 bg-hazard-void rounded-full overflow-hidden">
559	          <div
560	            className="h-full bg-gradient-to-r from-hazard-cyan to-hazard-gold transition-all duration-75"
561	            style={{ width: `${Math.max(10, scrollProgress)}%` }}
562	          />
563	        </div>
564	
